class Solution {
public:
    int maxValueOfCoins(vector<vector<int>>& piles, int k) {
        vector<int> dp(k + 1, 0);
        for (const auto& pile : piles) {
            vector<int> pref = {0};
            for (int x : pile) pref.push_back(pref.back() + x);
            for (int j = k; j >= 0; j--) {
                for (int c = 1; c <= min((int)pile.size(), j); c++) {
                    dp[j] = max(dp[j], dp[j - c] + pref[c]);
                }
            }
        }
        return dp[k];
    }
};

class Solution {
    public int maxValueOfCoins(List<List<Integer>> piles, int k) {
        int[] dp = new int[k + 1];
        for (List<Integer> pile : piles) {
            int m = pile.size();
            int[] pref = new int[m + 1];
            for (int i = 0; i < m; i++) pref[i + 1] = pref[i] + pile.get(i);
            for (int j = k; j >= 0; j--) {
                for (int c = 1; c <= Math.min(m, j); c++) {
                    dp[j] = Math.max(dp[j], dp[j - c] + pref[c]);
                }
            }
        }
        return dp[k];
    }
}

/**
 * @param {number[][]} piles
 * @param {number} k
 * @return {number}
 */
var maxValueOfCoins = function(piles, k) {
    const dp = new Array(k + 1).fill(0);
    for (const pile of piles) {
        const m = pile.length;
        const pref = new Array(m + 1).fill(0);
        for (let i = 0; i < m; i++) pref[i + 1] = pref[i] + pile[i];
        for (let j = k; j >= 0; j--) {
            for (let c = 1; c <= Math.min(m, j); c++) {
                dp[j] = Math.max(dp[j], dp[j - c] + pref[c]);
            }
        }
    }
    return dp[k];
};
